CREATE TABLE "receivers" ("id" UUID PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES "tenants"("id"), "activity_id" UUID NOT NULL, "name" VARCHAR(160) NOT NULL, "version" INTEGER NOT NULL, FOREIGN KEY ("tenant_id","activity_id") REFERENCES "activities"("tenant_id","id"), UNIQUE("tenant_id","activity_id","version"));
CREATE TABLE "evidences" ("id" UUID PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES "tenants"("id"), "activity_id" UUID NOT NULL, "kind" VARCHAR(32) NOT NULL, "origin" VARCHAR(24) NOT NULL, "status" VARCHAR(24) NOT NULL DEFAULT 'initiated', "object_key" VARCHAR(500) NOT NULL UNIQUE, "mime_type" VARCHAR(120) NOT NULL, "expected_size" INTEGER NOT NULL CHECK ("expected_size">0), "actual_size" INTEGER, "expected_sha256" CHAR(64) NOT NULL, "sha256" CHAR(64), "version" INTEGER NOT NULL DEFAULT 1, "confirmed_at" TIMESTAMPTZ(3), FOREIGN KEY ("tenant_id","activity_id") REFERENCES "activities"("tenant_id","id"));
CREATE UNIQUE INDEX "evidences_tenant_id_id_key" ON "evidences"("tenant_id","id");
CREATE INDEX "evidences_policy_idx" ON "evidences"("tenant_id","activity_id","status","kind");
CREATE TABLE "proofs" ("id" UUID PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES "tenants"("id"), "activity_id" UUID NOT NULL, "version" INTEGER NOT NULL, "status" VARCHAR(24) NOT NULL DEFAULT 'pending', "manifest" JSONB NOT NULL, FOREIGN KEY ("tenant_id","activity_id") REFERENCES "activities"("tenant_id","id"));
CREATE UNIQUE INDEX "proofs_tenant_id_id_key" ON "proofs"("tenant_id","id");
CREATE UNIQUE INDEX "proofs_version_key" ON "proofs"("tenant_id","activity_id","version");
CREATE TABLE "proof_evidences" ("tenant_id" UUID NOT NULL, "proof_id" UUID NOT NULL, "evidence_id" UUID NOT NULL, PRIMARY KEY("tenant_id","proof_id","evidence_id"), FOREIGN KEY ("tenant_id","proof_id") REFERENCES "proofs"("tenant_id","id"), FOREIGN KEY ("tenant_id","evidence_id") REFERENCES "evidences"("tenant_id","id"));
